libraries.example:
import { createHudRegistry } from '@manygamescorp/ui-kit/services/hud-registry';
const registry = createHudRegistry({ now: () => sdk.time.now(), layout: () => ({ items: {} }), ignored: issue => console.log(issue.path, issue.code) });
const off = registry.onIgnored(issue => console.log(issue.path, issue.code));
off();

declarations:
export interface HudChangedEvent {
  /** Ids of the items whose view changed (all registered ids for `layout` and `reset`). */
  readonly ids: readonly string[];
  /**
   * Why: `register`, `unregister`, `badge`, `state` (progress or state), `layout` (configuration
   * update), `tick` (timer badge, once a second) or `reset`.
   */
  readonly reason: HudChangeReason;
}

export interface HudDeps {
  /** Must be core.time.now; no wall-clock fallback. */
  readonly now: () => number;
  readonly enabled?: boolean;
  /** The layout record `ui.hud/layout` as the current configs snapshot has it. */
  readonly layout?: () => unknown;
  /** D-MATCH on the player's context (segments, platform…). */
  readonly match?: (filter: unknown) => boolean;
  /** An invalid part of the layout was ignored (once per distinct record, no values). */
  readonly ignored?: (issue: HudLayoutIssue) => void;
  readonly changed?: (change: HudChangedEvent) => void;
  readonly opened?: (id: string) => void;
  /** Has  a rule for this route key ()? Unset: not checked. */
  readonly hasWindowRule?: (key: string) => boolean;
  /** Reported when an item without onClick is opened and no rule answers it (client-sdk#1528). */
  readonly ruleMissing?: (issue: MissingWindowRule) => void;
  readonly timers?: {
    set(callback: () => void, ms: number): unknown;
    clear(handle: unknown): void;
  };
}

export interface HudOpenedEvent {
  /** Id of the opened item. */
  readonly id: string;
}

export interface HudRegistry {
  add(spec: HudItemSpec, owner?: string): boolean;
  remove(id: string, owner?: string): void;
  setValue(id: string, value: HudValue, owner?: string): void;
  setBadge(id: string, badge: HudBadgeInput | null, owner?: string): void;
  setTimer(id: string, endsAt: number | null, owner?: string): void;
  setProgress(id: string, progress: number | null, owner?: string): void;
  setState(id: string, state: HudItemState, owner?: string): void;
  items(): readonly HudItem[];
  open(id: string): void;
  relayout(): void;
  reset(): void;
  context(): string;
  setContext(context: string): void;
  setEnabled(enabled: boolean): void;
  onChange(listener: (change: HudChanged) => void): () => void;
  onOpen(listener: (id: string) => void): () => void;
  /** Subscribe to the ignored parts of the layout (same issues as `deps.ignored`). */
  onIgnored(listener: (issue: HudLayoutIssue) => void): () => void;
}
